use crate::content::{self, StatusSet};
pub fn shadow_form(hero: usize, awake_visible: bool, statuses: StatusSet) -> bool {
    let mut dark = awake_visible;
    content::dispatch_rules(
        &content::EventContext::new(
            hero,
            0,
            0,
            content::Rules {
                awake: awake_visible,
                statuses,
                ..Default::default()
            },
        ),
        &mut content::RuleEvent::Appearance { dark: &mut dark },
        &mut Vec::new(),
    );
    dark
}
#[cfg(test)]
mod nun_visual_tests {
    use super::*;
    use content::{Skill, StatusDuration, StatusId};
    #[test]
    fn nun_appearance_follows_permanent_and_temporary_effects() {
        let mut s = StatusSet::default();
        assert!(!shadow_form(content::NUN, false, s));
        s.insert(
            StatusId::Frenzy,
            Skill::Frenzy,
            StatusDuration::OwnerTurnEnd(1),
        );
        assert!(shadow_form(content::NUN, false, s));
        s = StatusSet::default();
        assert!(shadow_form(content::NUN, true, s));
        s.insert(
            StatusId::Rational,
            Skill::Rational,
            StatusDuration::OwnerTurnEnd(1),
        );
        assert!(!shadow_form(content::NUN, true, s));
    }
}

/// New-role atlases stack four rows: idle, awakened idle, cast, awakened cast.
/// Legacy sheets only carry idle frames, so they keep the idle row while casting.
pub const CAST_FRAMES: [&[usize]; 2] = [&[8, 9, 10, 11], &[12, 13, 14, 15]];
/// One cast frame per `CAST_TIME / 4`, so the animation fills the whole cast window.
pub const CAST_FRAME_TIME: [f64; 4] = [crate::presentation::CAST_TIME / 4.; 4];
pub fn cast_frames(hero: usize, shadow: bool) -> Option<&'static [usize]> {
    (hero >= content::KNIGHT).then(|| CAST_FRAMES[shadow as usize])
}
